import urllib.request, urllib.parse, json, ssl
ctx=ssl.create_default_context(); ua={'User-Agent':'Mozilla/5.0 ChatGPTTerrainResearch/1.0'}
def get(url):
    sep='&' if '?' in url else '?'
    req=urllib.request.Request(url+sep+'f=pjson',headers=ua)
    with urllib.request.urlopen(req,timeout=30,context=ctx) as r: return json.loads(r.read().decode('utf-8'))
